from unittest.mock import MagicMock
from unittest.mock import patch as mock_patch

from ansible_collections.vastdata.vms.plugins.modules.callhomeconfig_register_cluster import (
    CallhomeconfigRegisterCluster,
)


class TestAsyncBehavior:
    """Regression coverage for the 202/AsyncTaskInResponse detection fix.

    The swagger entry for /callhomeconfigs/{id}/register-cluster/ declares its
    AsyncTaskInResponse under HTTP 202. Before the parser fix, the response
    scan only inspected 200/201, so is_async ended up False and the module
    never polled the async task. These tests guard against that regression.
    """

    def test_class_marks_is_async(self):
        assert CallhomeconfigRegisterCluster.is_async is True

    def test_update_waits_for_task(self):
        resource = CallhomeconfigRegisterCluster.__new__(CallhomeconfigRegisterCluster)
        resource.module = MagicMock()
        resource.is_async = True
        async_response = {"async_task": {"id": 42}}
        api_base = MagicMock()
        api_base.patch.return_value = async_response

        with mock_patch.object(
            type(resource), "_api_base", new_callable=lambda: property(lambda self: api_base)
        ), mock_patch.object(resource, "_wait_for_task") as wait_mock:
            result = resource.update({"token": "tok"})

        api_base.patch.assert_called_once_with(token="tok")
        wait_mock.assert_called_once_with(async_response)
        assert result == async_response
